"""Build items_scope.json. Deterministic. Sources are CARRIED (model memory), not fetched or verified here."""
import json

def S(id_, domain, statement, question, key, source, stamp, transport):
    return dict(id=id_, kind="scoped", domain=domain, statement=statement, question=question, key=key,
                source=source, source_status="CARRIED: from model memory, not fetched or verified in this session",
                stamp_terms=stamp, transport_terms=transport)

def C(id_, domain, statement, question, correct):
    return dict(id=id_, kind="control", domain=domain, statement=statement, question=question,
                key="no scope issue: the question sits inside the finding's own conditions",
                correct_terms=correct)

